import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
import Icon from 'flarum/common/components/Icon';
const t = (k, p) => app.translator.trans(`ernestdefoe-gameday.forum.watch_${k}`, p);
const KIND_ICON = {
  tv: 'fas fa-tv',
  streaming: 'fas fa-play',
  radio: 'fas fa-radio'
};

/**
 * One network as a chip.
 *
 * 🚨 Styled text, not logos. A network's mark is its trademark, and nothing
 * here has permission to bundle one — a recognisable name in a consistent chip
 * reads at a glance anyway, and never goes stale when a network redraws its
 * logo. The medium is an icon WITH a label behind it, never the icon alone.
 */
function chip(c) {
  const kind = extractText(t(`kind_${c.kind}`));
  const local = c.market !== 'national' && c.team ? extractText(t('local', {
    team: c.team
  })) : '';
  const sub = c.subscription ? extractText(t('subscription')) : '';
  const title = [c.label, kind, local, sub].filter(Boolean).join(' · ');
  return m("li", {
    className: `GamedayWatch-chip GamedayWatch-chip--${c.kind}${c.market !== 'national' ? ' GamedayWatch-chip--local' : ''}`,
    title: title
  }, m(Icon, {
    name: KIND_ICON[c.kind] || KIND_ICON.tv,
    className: "GamedayWatch-kind"
  }), m("span", {
    className: "sr-only"
  }, kind, ": "), m("span", {
    className: "GamedayWatch-name"
  }, c.label), local ? m("span", {
    className: "GamedayWatch-local"
  }, local) : null, sub ? m("span", {
    className: "GamedayWatch-sub"
  }, sub) : null);
}

/**
 * The chips and, before the final whistle, the button.
 *
 * `withButton` is false in a widget strip holding several games: six Watch
 * buttons in a row of cards is a wall of calls to action, and the thread a
 * card links to has the button.
 */
export function watchRow(w, className, withButton) {
  if (withButton === void 0) {
    withButton = true;
  }
  if (!w || !w.channels || w.channels.length === 0) return null;
  const button = withButton && !w.compact && w.watch ? w.watch : null;
  return m("div", {
    className: `GamedayWatch ${className}${w.compact ? ' GamedayWatch--compact' : ''}`
  }, m("span", {
    className: "GamedayWatch-caption"
  }, t(w.compact ? 'caption_final' : 'caption')), m("ul", {
    className: "GamedayWatch-chips"
  }, w.channels.map(chip)), button ? m("a", {
    className: "GamedayWatch-button",
    href: button.url,
    target: "_blank",
    rel: "noopener noreferrer",
    "aria-label": extractText(t('button_label', {
      network: button.label
    }))
  }, m(Icon, {
    name: "fas fa-play",
    className: "GamedayWatch-buttonIcon"
  }), m("span", null, t('button', {
    network: button.label
  })), m(Icon, {
    name: "fas fa-arrow-up-right-from-square",
    className: "GamedayWatch-external"
  })) : null);
}